+    el.querySelectorAll('.cg-mode').forEach(b => b.onclick = () => { mode = b.dataset.mode; reset(); });
+
+    // select a slot (click) -> highlight its cipher letter group
+    el.querySelector('#cg-board').addEventListener('click', (e) => {
