+    };
+    document.addEventListener('keydown', onKey);
+    detachKeys = () => document.removeEventListener('keydown', onKey);
+  }
+
+  reset();
+  return { destroy() { if (detachKeys) detachKeys(); const g = document.querySelector('.cg-ghost'); if (g) g.remove(); } };
+}

